/** Encoder Code 128 (set B, ASCII 32–126). Tanpa dependency. */
export const PATTERNS = [
  "212222","222122","222221","121223","121322","131222","122213","122312","132212","221213",
  "221312","231212","112232","122132","122231","113222","123122","123221","223211","221132",
  "221231","213212","223112","312131","311222","321122","321221","312212","322112","322211",
  "212123","212321","232121","111323","131123","131321","112313","132113","132311","211313",
  "231113","231311","112133","112331","132131","113123","113321","133121","313121","211331",
  "231131","213113","213311","213131","311123","311321","331121","312113","312311","332111",
  "314111","221411","431111","111224","111422","121124","121421","141122","141221","112214",
  "112412","122114","122411","142112","142211","241211","221114","413111","241112","134111",
  "111242","121142","121241","114212","124112","124211","411212","421112","421211","212141",
  "214121","412121","111143","111341","131141","114113","114311","411113","411311","113141",
  "114131","311141","411131","211412","211214","211232","2331112",
];
const START_B = 104;
const STOP = 106;

export function sanitize128(text: string): string {
  return Array.from(text)
    .map((ch) => {
      const c = ch.charCodeAt(0);
      return c >= 32 && c <= 126 ? ch : "?";
    })
    .join("");
}

/** Mengembalikan nilai simbol (termasuk start, checksum, stop). */
export function code128Symbols(text: string): number[] {
  const s = sanitize128(text);
  const vals = Array.from(s).map((ch) => ch.charCodeAt(0) - 32);
  let sum = START_B;
  vals.forEach((v, i) => (sum += v * (i + 1)));
  return [START_B, ...vals, sum % 103, STOP];
}

/** Pola modul: true = bar hitam. Termasuk quiet zone 10 modul di kedua sisi. */
export function code128Modules(text: string): boolean[] {
  const mods: boolean[] = new Array(10).fill(false);
  for (const sym of code128Symbols(text)) {
    const p = PATTERNS[sym];
    for (let i = 0; i < p.length; i++) {
      const w = Number(p[i]);
      for (let k = 0; k < w; k++) mods.push(i % 2 === 0);
    }
  }
  for (let i = 0; i < 10; i++) mods.push(false);
  return mods;
}
